package com.factoryflow.materials;

import jakarta.persistence.*;
import org.hibernate.annotations.CreationTimestamp;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

/**
 * Entity mapping to the units table.
 * Represents a unit of measure (kg, g, litre, piece, etc.) and its
 * relationship to a base unit within the same unit type.
 */
@Entity
@Table(name = "units")
public class Unit {

    /** Primary key – UUID generated by the application. */
    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    @Column(name = "id", updatable = false, nullable = false)
    private UUID id;

    /** Full name of the unit, e.g. "Kilogram", "Litre", "Piece". */
    @Column(name = "name", nullable = false, length = 50)
    private String name;

    /** Short symbol used in UI and documents, e.g. "kg", "L", "pcs". */
    @Column(name = "symbol", nullable = false, length = 20)
    private String symbol;

    /**
     * Category / dimension this unit belongs to,
     * e.g. "WEIGHT", "VOLUME", "COUNT", "LENGTH".
     */
    @Column(name = "unit_type", nullable = true, length = 50)
    private String unitType;

    /**
     * Symbol of the base unit within this unit type.
     * For example, for "g" the base unit might be "kg"; for "ml" it might be "L".
     */
    @Column(name = "base_unit", nullable = true, length = 20)
    private String baseUnit;

    /**
     * Conversion factor to the base unit.
     * E.g. for grams: toBaseFactor = 0.001 (1 g = 0.001 kg).
     * Used for unit-of-measure conversions in BOM calculations.
     */
    @Column(name = "to_base_factor", nullable = true, precision = 20, scale = 10)
    private BigDecimal toBaseFactor;

    /** Audit timestamp set automatically on first insert. */
    @CreationTimestamp
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    public UUID getId() { return id; }
    public void setId(UUID id) { this.id = id; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getSymbol() { return symbol; }
    public void setSymbol(String symbol) { this.symbol = symbol; }
    public String getUnitType() { return unitType; }
    public void setUnitType(String unitType) { this.unitType = unitType; }
    public String getBaseUnit() { return baseUnit; }
    public void setBaseUnit(String baseUnit) { this.baseUnit = baseUnit; }
    public BigDecimal getToBaseFactor() { return toBaseFactor; }
    public void setToBaseFactor(BigDecimal toBaseFactor) { this.toBaseFactor = toBaseFactor; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
}
